import React from "react";

function formatAuthors(authors) {
  return authors
    .map((author) => `${author.name}${author.equal ? "**" : ""}`)
    .join(", ");
}

export default function PublicationCard({ publication }) {
  const { title, venue, authors, links, image, note } = publication;

  return (
    <article className="grid grid-cols-1 gap-6 sm:grid-cols-[180px_minmax(0,1fr)]">
      <div>
        {image ? (
            <img
                src={image}
                alt={title}
                className="aspect-[16/10] w-full rounded-md border border-neutral-200 bg-white object-contain p-2"
            />
            ) : (
          <div className="flex aspect-[4/3] w-full items-center justify-center rounded-md border border-neutral-200 bg-neutral-50 text-sm text-neutral-400">
            Image coming soon
          </div>
        )}
      </div>

      <div>
        <h3 className="text-lg font-medium leading-snug sm:text-xl">{title}</h3>

        <p className="mt-2 text-sm leading-6 text-neutral-700 sm:text-base">
          {formatAuthors(authors)}
        </p>

        <p className="mt-1 text-sm text-neutral-600 sm:text-base">{venue}</p>

        <div className="mt-3 flex flex-wrap items-center gap-x-3 gap-y-2 text-sm sm:text-base">
          {links.map((link, index) => (
            <React.Fragment key={link.label}>
              <a
                href={link.href}
                target="_blank"
                rel="noopener noreferrer"
                className="underline underline-offset-2 hover:text-neutral-600"
              >
                {link.label}
              </a>
              {index < links.length - 1 && (
                <span className="text-neutral-400">/</span>
              )}
            </React.Fragment>
          ))}
        </div>

        {note && <p className="mt-2 text-sm text-neutral-500">{note}</p>}
      </div>
    </article>
  );
}
